CREATE FUNCTION public.tr_slugify(input_text text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT trim(
        both '-'
        FROM regexp_replace(
            lower(
                translate(
                    coalesce(input_text, ''),
                    'ÇçĞğİIıÖöŞşÜü',
                    'CcGgIIiOoSsUu'
                )
            ),
            '[^a-z0-9]+',
            '-',
            'g'
        )
    );
$$;


